import { useState, type ChangeEvent } from 'react';
import {
  Box,
  Stack,
  Text,
  Button,
  Input,
  Field,
  Steps,
  Step,
} from '@jinx-ui/react';

type ContactsData = {
  fullName: string;
  email: string;
  phone: string;
};

type AddressData = {
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationData = {
  contacts: ContactsData;
  address: AddressData;
};

type RegistrationWizardProps = {
  onSubmit: (data: RegistrationData) => void;
};

const STEP_TITLES = ['Контакты', 'Адрес', 'Проверка'];

function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [stepIndex, setStepIndex] = useState(0);
  const [contacts, setContacts] = useState<ContactsData>({
    fullName: '',
    email: '',
    phone: '',
  });
  const [address, setAddress] = useState<AddressData>({
    country: '',
    city: '',
    street: '',
    zip: '',
  });

  const isFirstStep = stepIndex === 0;
  const isLastStep = stepIndex === STEP_TITLES.length - 1;

  const updateContacts = (field: keyof ContactsData) =>
    (event: ChangeEvent<HTMLInputElement>) =>
      setContacts((previous) => ({ ...previous, [field]: event.target.value }));

  const updateAddress = (field: keyof AddressData) =>
    (event: ChangeEvent<HTMLInputElement>) =>
      setAddress((previous) => ({ ...previous, [field]: event.target.value }));

  const goBack = () => setStepIndex((current) => Math.max(0, current - 1));
  const goNext = () => setStepIndex((current) => Math.min(STEP_TITLES.length - 1, current + 1));
  const handleSubmit = () => onSubmit({ contacts, address });

  return (
    <Box className="jx-registration-wizard">
      <Steps current={stepIndex} className="jx-registration-wizard__steps">
        {STEP_TITLES.map((title) => (
          <Step key={title} title={title} />
        ))}
      </Steps>

      <Box className="jx-registration-wizard__content">
        {stepIndex === 0 && (
          <Stack direction="column" gap="md">
            <Field label="Имя и фамилия">
              <Input value={contacts.fullName} onChange={updateContacts('fullName')} placeholder="Иван Иванов" />
            </Field>
            <Field label="Email">
              <Input type="email" value={contacts.email} onChange={updateContacts('email')} placeholder="ivan@example.com" />
            </Field>
            <Field label="Телефон">
              <Input type="tel" value={contacts.phone} onChange={updateContacts('phone')} placeholder="+7 900 000-00-00" />
            </Field>
          </Stack>
        )}

        {stepIndex === 1 && (
          <Stack direction="column" gap="md">
            <Field label="Страна">
              <Input value={address.country} onChange={updateAddress('country')} />
            </Field>
            <Field label="Город">
              <Input value={address.city} onChange={updateAddress('city')} />
            </Field>
            <Field label="Улица и дом">
              <Input value={address.street} onChange={updateAddress('street')} />
            </Field>
            <Field label="Индекс">
              <Input value={address.zip} onChange={updateAddress('zip')} />
            </Field>
          </Stack>
        )}

        {stepIndex === 2 && (
          <Stack direction="column" gap="md">
            <Text weight="bold">Контакты</Text>
            <Text>{contacts.fullName}</Text>
            <Text>{contacts.email}</Text>
            <Text>{contacts.phone}</Text>
            <Text weight="bold">Адрес</Text>
            <Text>{address.country}, {address.city}, {address.street}</Text>
            <Text>{address.zip}</Text>
          </Stack>
        )}
      </Box>

      <Stack direction="row" justify="space-between" className="jx-registration-wizard__actions">
        <Button variant="secondary" onClick={goBack} disabled={isFirstStep}>
          Назад
        </Button>
        {isLastStep ? (
          <Button variant="primary" onClick={handleSubmit}>
            Отправить
          </Button>
        ) : (
          <Button variant="primary" onClick={goNext}>
            Дальше
          </Button>
        )}
      </Stack>
    </Box>
  );
}

export default RegistrationWizard;

